import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        final long MOD_CONST = 1000000007L;
        Scanner scanner = new Scanner(System.in);
        int p_value = scanner.nextInt();
        int k_value = scanner.nextInt();
        int total_cycles;

        if (k_value == 0) {
            total_cycles = p_value - 1;
        } else if (k_value == 1) {
            total_cycles = p_value;
        } else {
            total_cycles = 0;
            boolean[] visited_nodes = new boolean[p_value];
            for (int start_node = 1; start_node < p_value; start_node++) {
                if (!visited_nodes[start_node]) {
                    visited_nodes[start_node] = true;
                    total_cycles++;
                    int j = (int)((long)start_node * k_value % p_value);
                    while (!visited_nodes[j]) {
                        visited_nodes[j] = true;
                        j = (int)((long)j * k_value % p_value);
                    }
                }
            }
        }

        long product_result = 1;
        for (int i = 0; i < total_cycles; i++) {
            product_result = (product_result * p_value) % MOD_CONST;
        }
        System.out.println(product_result);
        scanner.close();
    }
}
